package br.edu.oficinacampus.dominio.recursos;

import br.edu.oficinacampus.dominio.compartilhado.*;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.stream.Stream;
import static org.junit.jupiter.api.Assertions.*;

/** Constrói os agregados diretamente: regras não dependem do JSON da interface. */
class InvariantesRecursosTest {
    @TestFactory Stream<DynamicTest> invariantesDosAgregados() {
        List<DynamicTest> testes = new ArrayList<>();
        testes.add(DynamicTest.dynamicTest("equipamentos: exemplo válido", () -> assertDoesNotThrow(() -> new FichaEquipamento(Controle.novo(Estado.ATIVO), "Projetor portátil", "Audiovisual", "Conectar o cabo HDMI antes de ligar.", java.util.List.of("oficinas-0")))));
        testes.add(DynamicTest.dynamicTest("equipamentos/nome: obrigatório", () -> assertThrows(ErroDominio.class, () -> new FichaEquipamento(Controle.novo(Estado.ATIVO), null, "Audiovisual", "Conectar o cabo HDMI antes de ligar.", java.util.List.of("oficinas-0")))));
        testes.add(DynamicTest.dynamicTest("equipamentos/nome: texto extenso", () -> assertThrows(ErroDominio.class, () -> new FichaEquipamento(Controle.novo(Estado.ATIVO), "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Audiovisual", "Conectar o cabo HDMI antes de ligar.", java.util.List.of("oficinas-0")))));
        testes.add(DynamicTest.dynamicTest("equipamentos/nome: texto curto", () -> assertThrows(ErroDominio.class, () -> new FichaEquipamento(Controle.novo(Estado.ATIVO), "x", "Audiovisual", "Conectar o cabo HDMI antes de ligar.", java.util.List.of("oficinas-0")))));
        testes.add(DynamicTest.dynamicTest("equipamentos/tipo: obrigatório", () -> assertThrows(ErroDominio.class, () -> new FichaEquipamento(Controle.novo(Estado.ATIVO), "Projetor portátil", null, "Conectar o cabo HDMI antes de ligar.", java.util.List.of("oficinas-0")))));
        testes.add(DynamicTest.dynamicTest("equipamentos/tipo: opção inválida", () -> assertThrows(ErroDominio.class, () -> new FichaEquipamento(Controle.novo(Estado.ATIVO), "Projetor portátil", "Inexistente", "Conectar o cabo HDMI antes de ligar.", java.util.List.of("oficinas-0")))));
        testes.add(DynamicTest.dynamicTest("equipamentos/instrucoes: opcional", () -> assertDoesNotThrow(() -> new FichaEquipamento(Controle.novo(Estado.ATIVO), "Projetor portátil", "Audiovisual", null, java.util.List.of("oficinas-0")))));
        testes.add(DynamicTest.dynamicTest("equipamentos/instrucoes: texto extenso", () -> assertThrows(ErroDominio.class, () -> new FichaEquipamento(Controle.novo(Estado.ATIVO), "Projetor portátil", "Audiovisual", "", java.util.List.of("oficinas-0")))));
        testes.add(DynamicTest.dynamicTest("equipamentos/oficinas: opcional", () -> assertDoesNotThrow(() -> new FichaEquipamento(Controle.novo(Estado.ATIVO), "Projetor portátil", "Audiovisual", "Conectar o cabo HDMI antes de ligar.", java.util.List.of()))));
        testes.add(DynamicTest.dynamicTest("equipamentos/oficinas: identidade inválida", () -> assertThrows(ErroDominio.class, () -> new FichaEquipamento(Controle.novo(Estado.ATIVO), "Projetor portátil", "Audiovisual", "Conectar o cabo HDMI antes de ligar.", java.util.List.of("duas palavras")))));
        testes.add(DynamicTest.dynamicTest("equipamentos/oficinas: sem repetição", () -> assertThrows(ErroDominio.class, () -> new FichaEquipamento(Controle.novo(Estado.ATIVO), "Projetor portátil", "Audiovisual", "Conectar o cabo HDMI antes de ligar.", java.util.List.of("oficinas-0", "oficinas-0")))));
        testes.add(DynamicTest.dynamicTest("parceiras: exemplo válido", () -> assertDoesNotThrow(() -> new InstituicaoParceira(Controle.novo(Estado.ATIVO), "Coletivo Horizonte", "Cultural", "parcerias@example.com", java.util.List.of("oficinas-0", "oficinas-2")))));
        testes.add(DynamicTest.dynamicTest("parceiras/nome: obrigatório", () -> assertThrows(ErroDominio.class, () -> new InstituicaoParceira(Controle.novo(Estado.ATIVO), null, "Cultural", "parcerias@example.com", java.util.List.of("oficinas-0", "oficinas-2")))));
        testes.add(DynamicTest.dynamicTest("parceiras/nome: texto extenso", () -> assertThrows(ErroDominio.class, () -> new InstituicaoParceira(Controle.novo(Estado.ATIVO), "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Cultural", "parcerias@example.com", java.util.List.of("oficinas-0", "oficinas-2")))));
        testes.add(DynamicTest.dynamicTest("parceiras/nome: texto curto", () -> assertThrows(ErroDominio.class, () -> new InstituicaoParceira(Controle.novo(Estado.ATIVO), "x", "Cultural", "parcerias@example.com", java.util.List.of("oficinas-0", "oficinas-2")))));
        testes.add(DynamicTest.dynamicTest("parceiras/modalidade: obrigatório", () -> assertThrows(ErroDominio.class, () -> new InstituicaoParceira(Controle.novo(Estado.ATIVO), "Coletivo Horizonte", null, "parcerias@example.com", java.util.List.of("oficinas-0", "oficinas-2")))));
        testes.add(DynamicTest.dynamicTest("parceiras/modalidade: opção inválida", () -> assertThrows(ErroDominio.class, () -> new InstituicaoParceira(Controle.novo(Estado.ATIVO), "Coletivo Horizonte", "Inexistente", "parcerias@example.com", java.util.List.of("oficinas-0", "oficinas-2")))));
        testes.add(DynamicTest.dynamicTest("parceiras/contato: opcional", () -> assertDoesNotThrow(() -> new InstituicaoParceira(Controle.novo(Estado.ATIVO), "Coletivo Horizonte", "Cultural", null, java.util.List.of("oficinas-0", "oficinas-2")))));
        testes.add(DynamicTest.dynamicTest("parceiras/contato: texto extenso", () -> assertThrows(ErroDominio.class, () -> new InstituicaoParceira(Controle.novo(Estado.ATIVO), "Coletivo Horizonte", "Cultural", "", java.util.List.of("oficinas-0", "oficinas-2")))));
        testes.add(DynamicTest.dynamicTest("parceiras/oficinas: opcional", () -> assertDoesNotThrow(() -> new InstituicaoParceira(Controle.novo(Estado.ATIVO), "Coletivo Horizonte", "Cultural", "parcerias@example.com", java.util.List.of()))));
        testes.add(DynamicTest.dynamicTest("parceiras/oficinas: identidade inválida", () -> assertThrows(ErroDominio.class, () -> new InstituicaoParceira(Controle.novo(Estado.ATIVO), "Coletivo Horizonte", "Cultural", "parcerias@example.com", java.util.List.of("duas palavras")))));
        testes.add(DynamicTest.dynamicTest("parceiras/oficinas: sem repetição", () -> assertThrows(ErroDominio.class, () -> new InstituicaoParceira(Controle.novo(Estado.ATIVO), "Coletivo Horizonte", "Cultural", "parcerias@example.com", java.util.List.of("oficinas-0", "oficinas-0")))));
        testes.add(DynamicTest.dynamicTest("kits: exemplo válido", () -> assertDoesNotThrow(() -> new KitMateriais(Controle.novo(Estado.ATIVO), "Kit de prototipação", "Apoiar atividades rápidas de ideação.", java.util.List.of("Bloco de notas adesivas", "Canetas coloridas", "Folhas de papel A4"), "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("kits/nome: obrigatório", () -> assertThrows(ErroDominio.class, () -> new KitMateriais(Controle.novo(Estado.ATIVO), null, "Apoiar atividades rápidas de ideação.", java.util.List.of("Bloco de notas adesivas", "Canetas coloridas", "Folhas de papel A4"), "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("kits/nome: texto extenso", () -> assertThrows(ErroDominio.class, () -> new KitMateriais(Controle.novo(Estado.ATIVO), "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Apoiar atividades rápidas de ideação.", java.util.List.of("Bloco de notas adesivas", "Canetas coloridas", "Folhas de papel A4"), "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("kits/nome: texto curto", () -> assertThrows(ErroDominio.class, () -> new KitMateriais(Controle.novo(Estado.ATIVO), "x", "Apoiar atividades rápidas de ideação.", java.util.List.of("Bloco de notas adesivas", "Canetas coloridas", "Folhas de papel A4"), "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("kits/finalidade: opcional", () -> assertDoesNotThrow(() -> new KitMateriais(Controle.novo(Estado.ATIVO), "Kit de prototipação", null, java.util.List.of("Bloco de notas adesivas", "Canetas coloridas", "Folhas de papel A4"), "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("kits/finalidade: texto extenso", () -> assertThrows(ErroDominio.class, () -> new KitMateriais(Controle.novo(Estado.ATIVO), "Kit de prototipação", "", java.util.List.of("Bloco de notas adesivas", "Canetas coloridas", "Folhas de papel A4"), "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("kits/componentes: obrigatório", () -> assertThrows(ErroDominio.class, () -> new KitMateriais(Controle.novo(Estado.ATIVO), "Kit de prototipação", "Apoiar atividades rápidas de ideação.", null, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("kits/componentes: lista vazia", () -> assertThrows(ErroDominio.class, () -> new KitMateriais(Controle.novo(Estado.ATIVO), "Kit de prototipação", "Apoiar atividades rápidas de ideação.", java.util.List.of(), "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("kits/componentes: componente vazio", () -> assertThrows(ErroDominio.class, () -> new KitMateriais(Controle.novo(Estado.ATIVO), "Kit de prototipação", "Apoiar atividades rápidas de ideação.", java.util.List.of(" "), "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("kits/componentes: componente extenso", () -> assertThrows(ErroDominio.class, () -> new KitMateriais(Controle.novo(Estado.ATIVO), "Kit de prototipação", "Apoiar atividades rápidas de ideação.", java.util.List.of("xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"), "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("kits/oficina: obrigatório", () -> assertThrows(ErroDominio.class, () -> new KitMateriais(Controle.novo(Estado.ATIVO), "Kit de prototipação", "Apoiar atividades rápidas de ideação.", java.util.List.of("Bloco de notas adesivas", "Canetas coloridas", "Folhas de papel A4"), null))));
        testes.add(DynamicTest.dynamicTest("kits/oficina: identidade inválida", () -> assertThrows(ErroDominio.class, () -> new KitMateriais(Controle.novo(Estado.ATIVO), "Kit de prototipação", "Apoiar atividades rápidas de ideação.", java.util.List.of("Bloco de notas adesivas", "Canetas coloridas", "Folhas de papel A4"), "duas palavras"))));
        testes.add(DynamicTest.dynamicTest("acessibilidade: exemplo válido", () -> assertDoesNotThrow(() -> new RecursoAcessibilidade(Controle.novo(Estado.ATIVO), "Materiais com fonte ampliada", "Visual", "Disponibilizar uma versão com fonte ampliada e alto contraste.", "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("acessibilidade/nome: obrigatório", () -> assertThrows(ErroDominio.class, () -> new RecursoAcessibilidade(Controle.novo(Estado.ATIVO), null, "Visual", "Disponibilizar uma versão com fonte ampliada e alto contraste.", "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("acessibilidade/nome: texto extenso", () -> assertThrows(ErroDominio.class, () -> new RecursoAcessibilidade(Controle.novo(Estado.ATIVO), "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Visual", "Disponibilizar uma versão com fonte ampliada e alto contraste.", "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("acessibilidade/nome: texto curto", () -> assertThrows(ErroDominio.class, () -> new RecursoAcessibilidade(Controle.novo(Estado.ATIVO), "x", "Visual", "Disponibilizar uma versão com fonte ampliada e alto contraste.", "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("acessibilidade/categoria: obrigatório", () -> assertThrows(ErroDominio.class, () -> new RecursoAcessibilidade(Controle.novo(Estado.ATIVO), "Materiais com fonte ampliada", null, "Disponibilizar uma versão com fonte ampliada e alto contraste.", "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("acessibilidade/categoria: opção inválida", () -> assertThrows(ErroDominio.class, () -> new RecursoAcessibilidade(Controle.novo(Estado.ATIVO), "Materiais com fonte ampliada", "Inexistente", "Disponibilizar uma versão com fonte ampliada e alto contraste.", "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("acessibilidade/orientacao: obrigatório", () -> assertThrows(ErroDominio.class, () -> new RecursoAcessibilidade(Controle.novo(Estado.ATIVO), "Materiais com fonte ampliada", "Visual", null, "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("acessibilidade/orientacao: texto extenso", () -> assertThrows(ErroDominio.class, () -> new RecursoAcessibilidade(Controle.novo(Estado.ATIVO), "Materiais com fonte ampliada", "Visual", "", "oficinas-0"))));
        testes.add(DynamicTest.dynamicTest("acessibilidade/oficina: obrigatório", () -> assertThrows(ErroDominio.class, () -> new RecursoAcessibilidade(Controle.novo(Estado.ATIVO), "Materiais com fonte ampliada", "Visual", "Disponibilizar uma versão com fonte ampliada e alto contraste.", null))));
        testes.add(DynamicTest.dynamicTest("acessibilidade/oficina: identidade inválida", () -> assertThrows(ErroDominio.class, () -> new RecursoAcessibilidade(Controle.novo(Estado.ATIVO), "Materiais com fonte ampliada", "Visual", "Disponibilizar uma versão com fonte ampliada e alto contraste.", "duas palavras"))));
        return testes.stream();
    }
}
